style:
.invoice-dashboard{
    font-family: Inter, sans-serif;
    padding: 10px;
    background: transparent;
}

/* Header */
.header{
    margin-bottom: 14px;
}

.header h3{
    margin: 0;
    font-size: 22px;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.2px;
}

/* Loading */
.loading{
    background: #ffffff;
    border: 1px dashed #d1d5db;
    border-radius: 12px;
    padding: 20px;
    text-align: center;
    font-size: 13px;
    font-weight: 700;
    color: #64748b;
}

/* Invoice Grid */
.invoice-grid{
    display: flex;
    flex-direction: column;
    gap: 12px;
}

/* Main Card */
.invoice-card{
    background: #ffffff;
    border: 1px solid #fde68a;
    border-radius: 14px;
    padding: 14px;
    position: relative;
    overflow: hidden;
    box-shadow: 0 2px 10px rgba(15,23,42,0.04);
    transition: 0.2s ease;
}

.invoice-card:hover{
    transform: translateY(-1px);
    box-shadow: 0 4px 14px rgba(15,23,42,0.06);
}

/* Accent */
.invoice-card::before{
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: linear-gradient(90deg,#f59e0b,#f97316);
}

/* Top Section */
.invoice-top{
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 10px;
    margin-bottom: 12px;
    padding-bottom: 10px;
    border-bottom: 1px solid #f1f5f9;
}

.invoice-id{
    font-size: 14px;
    font-weight: 800;
    color: #d97706;
}

.customer{
    display: none;
}

.amount{
    font-size: 18px;
    font-weight: 900;
    color: #c2410c;
    padding: 5px 10px;
    border-radius: 10px;
    border: 1px solid #fed7aa;
    background: transparent;
}

/* Details Grid */
.details-grid{
    display: grid;
    grid-template-columns: repeat(4,1fr);
    gap: 10px;
    margin-bottom: 12px;
}

/* Detail Box */
.detail-box{
    background: transparent;
    border: 1px solid #fed7aa;
    border-radius: 10px;
    padding: 10px;
    min-height: 64px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    transition: 0.2s ease;
}

.detail-box:hover{
    border-color: #fb923c;
}

.detail-box label{
    font-size: 10px;
    font-weight: 700;
    color: #9a3412;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    margin-bottom: 4px;
}

.detail-box p{
    margin: 0;
    font-size: 13px;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.4;
    word-break: break-word;
}

/* Duration Box */
.days-box{
    border-color: #facc15;
}

.days-box p{
    color: #b45309;
}

/* Full Width */
.full-width{
    grid-column: span 2;
}

/* Totals Section */
.totals-section{
    display: flex;
    flex-direction: column;
    gap: 10px;
}

/* Totals Grid */
.totals-grid{
    display: grid;
    grid-template-columns: repeat(4,1fr);
    gap: 10px;
}

/* Total Cards */
.total-card{
    background: transparent;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    padding: 10px;
    transition: 0.2s ease;
}

.total-card:hover{
    border-color: #cbd5e1;
}

.total-card label{
    display: block;
    font-size: 10px;
    font-weight: 700;
    color: #64748b;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    margin-bottom: 4px;
}

.total-card p{
    margin: 0;
    font-size: 15px;
    font-weight: 900;
    color: #0f172a;
}

/* Grand Total */
.total-card.grand{
    border-color: #fdba74;
}

.total-card.grand p{
    color: #c2410c;
}

/* Adjustment Card */
.adjustment-card{
    border: 1px solid #fde68a;
    border-radius: 12px;
    padding: 10px 14px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: transparent;
}

.adjustment-card label{
    font-size: 11px;
    font-weight: 800;
    color: #92400e;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.adjustment-card p{
    margin: 0;
    font-size: 16px;
    font-weight: 900;
    color: #d97706;
}

/* Tablet */
@media(max-width:768px){

    .details-grid,
    .totals-grid{
        grid-template-columns: repeat(2,1fr);
    }

    .full-width{
        grid-column: span 1;
    }

    .invoice-top{
        flex-direction: column;
        align-items: flex-start;
    }

    .amount{
        font-size: 16px;
    }
}

/* Mobile */
@media(max-width:480px){

    .invoice-dashboard{
        padding: 6px;
    }

    .details-grid,
    .totals-grid{
        grid-template-columns: 1fr;
    }

    .invoice-card{
        padding: 12px;
    }

    .header h3{
        font-size: 18px;
    }

    .amount{
        width: 100%;
        text-align: center;
        font-size: 16px;
    }

    .detail-box,
    .total-card{
        min-height: auto;
    }

    .adjustment-card{
        flex-direction: column;
        align-items: flex-start;
        gap: 4px;
    }

    .adjustment-card p{
        font-size: 15px;
    }
}

script:
const getShadowElement = (id) => {
    let el = document.getElementById(id);
    if (el) return el;

    let elements = document.querySelectorAll('*');
    for (let i = 0; i < elements.length; i++) {
        if (elements[i].shadowRoot) {
            let found = elements[i].shadowRoot.getElementById(id);
            if (found) return found;
        }
    }
    return null;
};

const loadMyPackages = () => {
    const container = getShadowElement("apps_subscription_block");

    if (!container) {
        setTimeout(loadMyPackages, 200);
        return;
    }

    try {
        frappe.call({
            method: "quantbit_billing_platform.quantbit_billing_platform.doctype.billing_account_master.billing_account_master.get_user_package",
            callback: function(r) {

                if (r.message && r.message.length > 0) {

                    let html = '<div class="subscription-grid">';

                    r.message.forEach(app => {

                        let cleanName = app.app_name ? app.app_name.replace(/_/g, ' ') : "App";

                        let days = app.days_remaining || 0;
                        let tokens = app.remaining_tokens || 0;
                        let isToken = app.package_type === "Token Based";
                        let badgeClass = days <= 7 ? 'warning' : '';

                        html += `
                            <div class="app-card">
                                <div class="app-title">${cleanName}</div>

                                <div class="info-row">
                                    <span class="info-label">Package</span>
                                    <span class="info-value">${app.billing_package || "-"}</span>
                                </div>

                                <div class="info-row">
                                    <span class="info-label">Role</span>
                                    <span class="info-value">${app.role || "-"}</span>
                                </div>

                                <div class="info-row">
                                    <span class="info-label">Valid Until</span>
                                    <span class="info-value">${app.to_date || "-"}</span>
                                </div>

                                ${isToken ? `
                                    <div class="days-container">
                                        <span class="info-label">Remaining Tokens</span>
                                        <span class="days-badge ${tokens <= 10 ? 'warning' : ''}">
                                            ${tokens} Tokens
                                        </span>
                                    </div>
                                ` : `
                                    <div class="days-container">
                                        <span class="info-label">Days Left</span>
                                        <span class="days-badge ${badgeClass}">
                                            ${days} Days
                                        </span>
                                    </div>
                                `}
                            </div>
                        `;
                    });

                    html += '</div>';
                    container.innerHTML = html;

                } else {
                    container.innerHTML = '<div style="padding:20px; color:#666;">No active packages found.</div>';
                }
            },
            error: function(err) {
                container.innerHTML = `<div style="color:red; padding:20px;">Error: Could not load data.</div>`;
            }
        });
    } catch (e) {
        container.innerHTML = `<div style="color:red; padding:20px;">An error occurred.</div>`;
    }
};

loadMyPackages();

