script:
let allPackages = [];
let currentAppFilter = 'all';
let currentTypeFilter = 'all';

const container = root_element;

setTimeout(() => {
    loadPackages();
}, 200);

async function loadPackages() {
    const res = await frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Billing Package',
            fields: [
                'name',
                'package_name',
                'no_of_users',
                'amount',
                'app',
                'package_type',
                'no_of_days',
                'is_base_package',
                'is_active'
            ],
            limit_page_length: 0
        }
    });

    allPackages = res.message || [];
    buildFilters();
    renderDashboard();
}

function buildFilters() {
    const appContainer = container.querySelector('#app-filter-buttons');
    const typeContainer = container.querySelector('#type-filter-buttons');

    const apps = [...new Set(allPackages.map(p => p.app).filter(Boolean))];
    const types = [...new Set(allPackages.map(p => p.package_type).filter(Boolean))];

    apps.forEach(app => {
        const btn = document.createElement('button');
        btn.className = 'filter-btn';
        btn.innerText = app;
        btn.onclick = () => {
            currentAppFilter = app;
            updateActiveButtons();
            renderDashboard();
        };
        appContainer.appendChild(btn);
    });

    types.forEach(type => {
        const btn = document.createElement('button');
        btn.className = 'filter-btn';
        btn.innerText = type;
        btn.onclick = () => {
            currentTypeFilter = type;
            updateActiveButtons();
            renderDashboard();
        };
        typeContainer.appendChild(btn);
    });

    // All buttons
    appContainer.querySelector('[data-filter="all"]').onclick = () => {
        currentAppFilter = 'all';
        updateActiveButtons();
        renderDashboard();
    };

    typeContainer.querySelector('[data-type="all"]').onclick = () => {
        currentTypeFilter = 'all';
        updateActiveButtons();
        renderDashboard();
    };
}

function updateActiveButtons() {
    container.querySelectorAll('#app-filter-buttons .filter-btn').forEach(btn => {
        btn.classList.toggle('active',
            btn.innerText === currentAppFilter ||
            (btn.innerText === 'All Apps' && currentAppFilter === 'all')
        );
    });

    container.querySelectorAll('#type-filter-buttons .filter-btn').forEach(btn => {
        btn.classList.toggle('active',
            btn.innerText === currentTypeFilter ||
            (btn.innerText === 'All Types' && currentTypeFilter === 'all')
        );
    });
}

function renderDashboard() {
    let filtered = allPackages.filter(p =>
        (currentAppFilter === 'all' || p.app === currentAppFilter) &&
        (currentTypeFilter === 'all' || p.package_type === currentTypeFilter)
    );

    renderStats(filtered);
    renderPackages(filtered);
}

function renderStats(packages) {
    const stats = container.querySelector('#stats-container');

    const active = packages.filter(p => p.is_active).length;
    const base = packages.filter(p => p.is_base_package).length;

    stats.innerHTML = `
        <div class="stat-card">
            <div class="stat-title">Total Plans</div>
            <div class="stat-value">${packages.length}</div>
        </div>
        <div class="stat-card">
            <div class="stat-title">Active Plans</div>
            <div class="stat-value">${active}</div>
        </div>
        <div class="stat-card">
            <div class="stat-title">Base Packages</div>
            <div class="stat-value">${base}</div>
        </div>
    `;
}

function renderPackages(packages) {
    const content = container.querySelector('#packages-content');

    if (!packages.length) {
        content.innerHTML = "<div class='loading'>No Packages Found</div>";
        return;
    }

    const html = packages.map(pkg => `
        <div class="package-card">
            <div class="package-name">${pkg.package_name || 'Standard Plan'}</div>

            <div class="price">₹${pkg.amount || 0}</div>

            <div class="meta">Users: ${pkg.no_of_users || 0}</div>
            <div class="meta">Days: ${pkg.no_of_days || 0}</div>
            <div class="meta">Type: ${pkg.package_type || '-'}</div>
            <div class="meta">App: ${pkg.app || '-'}</div>

            <div class="badges">
                ${pkg.is_active ? '<span class="badge active">Active</span>' : ''}
                ${pkg.is_base_package ? '<span class="badge base">Base</span>' : ''}
            </div>
        </div>
    `).join('');

    content.innerHTML = `<div class="packages-grid">${html}</div>`;
}

style:
.billing-dashboard {
    font-family: Inter, sans-serif;
}

.header h1 {
    font-size: 26px;
    margin-bottom: 5px;
    color: white;
    text-align: center;
}

.header p {
    color: #6b7280;
    font-size: 14px;
}

/* Stats */
.stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 15px;
    margin: 20px 0;
}

.stat-card {
    background: white;
    border: 1px solid #e5e7eb;
    padding: 18px;
    border-radius: 10px;
}

.stat-title {
    font-size: 13px;
    color: #6b7280;
}

.stat-value {
    font-size: 26px;
    font-weight: 700;
    margin-top: 5px;
}

/* Filters */
.filters {
    display: flex;
    gap: 40px;
    margin-bottom: 20px;
}

.filter-group label {
    font-size: 12px;
    color: #6b7280;
    display: block;
    margin-bottom: 8px;
}

.filter-buttons {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}

.filter-btn {
    padding: 6px 12px;
    border-radius: 6px;
    border: 1px solid #d1d5db;
    background: white;
    cursor: pointer;
}

.filter-btn.active {
    background: #2563eb;
    color: white;
    border-color: #2563eb;
}

