.packages-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 18px;
}

.package-card {
    background: white;
    border-radius: 10px;
    padding: 18px;
    border: 1px solid #e5e7eb;
